<section class="narrow page-heading"><span class="eyebrow">Create an account</span><h1>Start with your email</h1><p>Your profile is private and can be updated or deleted at any time.</p><form method="post" class="form-card"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="register"><div class="field"><label for="name">Full name</label><input id="name" name="name" required maxlength="120" autocomplete="name"></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" required minlength="10" autocomplete="new-password"><small>Use at least 10 characters, including a letter and a number.</small></div><div class="field"><label for="password_confirm">Confirm password</label><input id="password_confirm" name="password_confirm" type="password" required autocomplete="new-password"></div><label class="check-row"><input type="checkbox" name="terms" value="1" required><span>I accept the <a href="<?=e(url('privacy'))?>">privacy notice and terms</a>.</span></label><button class="button full" type="submit">Create account</button></form><p class="center muted">Already registered? <a href="<?=e(url('login'))?>">Sign in</a></p></section>
